import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Counter counter = new Counter();
        for(int i = 0; i < n; i++) {
            counter.increment();
        }
        System.out.println(counter.getCount());
    }
}

class Counter {
    private int count = 0;

    void increment() {
        count++;
    }

    int getCount() {
        return count;
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Book book = new Book();
        book.setDetails(sc.next(), sc.next(), sc.nextDouble());
        System.out.println(book.summary());
    }
}

class Book {
    private String title;
    private String author;
    private double price;

    void setDetails(String t, String a, double p) {
        title = t;
        author = a;
        price = p;
    }

    String summary() {
        return title + " by " + author + " costs " + String.format("%.2f", price);
    }
}

