import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Point p = new Point();
        p.x = sc.nextDouble();
        p.y = sc.nextDouble();
        System.out.printf("%.2f%n", p.distanceFromOrigin());
    }
}

class Point {
    double x;
    double y;

    double distanceFromOrigin() {
        return Math.sqrt(x * x + y * y);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Pet p1 = readPet(sc);
        Pet p2 = readPet(sc);
        System.out.println(p1.name + " says " + p1.speak());
        System.out.println(p2.name + " says " + p2.speak());
    }

    static Pet readPet(Scanner sc) {
        String type = sc.next();
        Pet p;
        if(type.equals("Dog")) {
            p = new Dog();
        } else {
            p = new Cat();
        }
        p.name = sc.next();
        return p;
    }
}

class Pet {
    String name;

    String speak() {
        return "...";
    }
}

class Dog extends Pet {
    String speak() {
        return "Woof";
    }
}

class Cat extends Pet {
    String speak() {
        return "Meow";
    }
}
